<script setup lang="ts">
/**
 * A file attached to a prompt, shown as a chip (`design/components/attachment-chip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/attachment-chip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, formatBytes, useListening, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/attachment-chip.module.css'
import Button from '../controls/Button.vue'
import Link from '../controls/Link.vue'
import Spinner from '../structure/Spinner.vue'

export type AttachmentStatus = 'uploading' | 'done' | 'error'

export interface AttachmentChipProps {
  /**
   * The file's URL, which makes the name a link that opens in a new tab (Link's `external`).
   */
  href?: string
  /**
   * The leading mark, `document` by default, or `table` or `browser` when the app knows the
   * kind.
   */
  icon?: IconRole
  /**
   * The app's text for a failure, which the chip never writes itself.
   */
  message?: string
  /**
   * The file's name, ellipsed when the row is narrow.
   */
  name: string
  /**
   * The remove button's accessible name (default `Remove {name}`), which apps pass to localize.
   */
  removeLabel?: string
  /**
   * The size in bytes, formatted by the engine's `formatBytes`, as FileUpload's rows are, so
   * sizes match in both places.
   */
  size?: number
  /**
   * The upload status, where `done` is the rest state.
   */
  status?: 'error' | 'uploading' | 'done'
  /**
   * The status announced while the file uploads (default `{name}: uploading`), which apps pass
   * to localize.
   */
  uploadingLabel?: string
}

defineOptions({ name: 'AttachmentChip', inheritAttrs: false })

const props = withDefaults(defineProps<AttachmentChipProps>(), { icon: 'document', status: 'done' })
const emit = defineEmits<{ remove: [] }>()
const listening = useListening()
const chip = useTemplateRef<HTMLElement>('chip')
const file = useTemplateRef<HTMLElement>('file')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'AttachmentChip',
    element: () => file.value,
    state: () => ({ name: props.name, status: props.status }),
    actions: {
      remove: () =>
        (() => {
          if (!listening.remove)
            throw new Error('The chip records a sent file and has no remove control.')
          emit('remove')
        })(),
    },
    withholds: () => chip.value,
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <span ref="chip" :class="styles.chip" :data-status="status" data-member="attachment-chip">
    <!-- mark -->
    <span :class="styles.mark">
      <Spinner
        v-if="status === 'uploading'"
        size="sm"
        :label="uploadingLabel ?? `${name}: uploading`"
      />
      <Icon v-else-if="status === 'error'" name="error" size="sm" />
      <Icon v-else :name="icon" size="sm" />
    </span>
    <!-- body -->
    <span :class="styles.body">
      <!-- name -->
      <span ref="file" :class="styles.name">
        <template v-if="href === undefined">{{ name }}</template>
        <Link v-else :href="href" :external="true">
          {{ name }}
        </Link>
      </span>
      <!-- meta -->
      <span v-if="size !== undefined && status !== 'error'" :class="styles.meta">
        {{ formatBytes(size) }}
      </span>
      <!-- message -->
      <span v-if="status === 'error' && message !== undefined" :class="styles.message">
        {{ message }}
      </span>
    </span>
    <Button
      v-if="listening.remove"
      variant="ghost"
      tone="neutral"
      size="sm"
      :iconOnly="true"
      icon="close"
      :label="removeLabel ?? `Remove ${name}`"
      @click="emit('remove')"
    />
  </span>
</template>
